// Early-primary visual activities interpreted from the teacher's unlabelled reference.
const PRIMARY={
 blocks:{name:'Block Builder',icon:'🧱',rule:'Copy the block model. Tap each square to cycle its height from 0 to 3, then check. Teacher answer: nine heights (0–3) separated by |.'},
 shapezones:{name:'Shape Detective',icon:'🔺',rule:'Which shapes contain the ladybird? Select every shape that contains it, then check. Teacher answer: circle, square or triangle, joined with | for overlaps.'},
 fruitsudoku:{name:'Picture Sudoku',icon:'🍊',rule:'Put each picture once in every row and column. Choose a picture, then tap an empty square. Teacher answer: three different pictures or short words separated by |.'},
 analogy:{name:'Picture Analogies',icon:'💜',rule:'Look at how the first shape changes. Choose the picture that completes the same change. Teacher answer: heart, star, circle or triangle.'},
 pathtrace:{name:'Follow the Path',icon:'🦋',subject:'english',rule:'Start at the green dot. Drag along the dotted path to the flower. Lift your pen between strokes. Teacher answer: a path number from 1 to 6.'},
 countpictures:{name:'Count and Match',icon:'🔢',rule:'Count the pictures and choose the matching number. Teacher answer: a whole number from 1 to 12.'},
 numbertrace:{name:'Number Tracing',icon:'✏️',rule:'Trace the number from the green dot, following the dots in order. Lift your pen between strokes. Teacher answer: one digit, 0–9.'},
 missingpicture:{name:'Missing Picture Piece',icon:'🐵',rule:'Find the piece that completes the picture. Teacher answer: monkey, cat, bear or frog.'},
 emotions:{name:'Feelings Faces',icon:'😊',subject:'english',rule:'Read the feeling and choose the matching face. Teacher answer: happy, sad, surprised, angry, worried or sleepy.'},
 symbolgrid:{name:'Picture Maths Grid',icon:'🧮',rule:'Use the row and column totals to work out the hidden picture values. Type the value of the highlighted picture. Teacher answer: three whole-number values (1–9), separated by |.'},
 symmetrydraw:{name:'Symmetry Drawing',icon:'🪞',rule:'Copy the orange line on the other side of the mirror. Tap the reflected dots in order; Undo lets you fix a point. Teacher answer: left-side points x,y separated by |, using x 0–3 and y 0–4.'},
 picturestrips:{name:'Picture Strip Puzzle',icon:'🧩',rule:'Rebuild the picture from left to right. Tap or drag strips into the empty slots. Tap a placed strip to undo it. Teacher answer: monkey, cat, bear or frog.'},
 pictureadd:{name:'Picture Addition',icon:'🐯',rule:'Count both groups of pictures and find the total. Teacher answer: two whole numbers from 1 to 9 separated by |.'},
 rotatepicture:{name:'Turn the Tiles',icon:'🔄',rule:'Rotate each tile a quarter-turn to copy the model. All four tiles must face the correct way. Teacher answer: four rotations (0–3) separated by |.'},
 directions:{name:'Direction Patterns',icon:'⬆️',rule:'Work out how the top arrow turns, then apply that turn to the bottom arrow. Teacher answer: a starting direction and a turn, for example up|right. Turns: right, left or half.'},
 lettertrace:{name:'Letter Tracing',icon:'🔤',subject:'english',rule:'Trace the capital letter from the green dot. Follow each stroke in order and lift your pen between strokes. Teacher answer: one capital letter A–Z.'}
};
const PR_FEEL={happy:'😊',sad:'😢',surprised:'😮',angry:'😠',worried:'😟',sleepy:'😴'};
const PR_ANIMALS=['monkey','cat','bear','frog'], PR_SHAPES=['circle','square','triangle'];
const PR_LETTERS={
 A:['100,230 200,30 300,230','145,145 255,145'],B:['110,230 110,30 230,30 280,65 230,125 110,125','230,125 285,175 250,230 110,230'],C:['290,55 245,30 150,30 105,75 105,185 150,230 245,230 290,205'],D:['110,230 110,30 220,30 285,85 285,175 220,230 110,230'],E:['285,30 110,30 110,230 285,230','110,125 250,125'],F:['110,230 110,30 285,30','110,125 250,125'],G:['290,55 245,30 150,30 105,75 105,185 150,230 270,230 290,150 220,150'],H:['110,30 110,230','290,30 290,230','110,130 290,130'],I:['130,30 270,30','200,30 200,230','130,230 270,230'],J:['130,30 280,30 280,185 245,230 160,230 115,185'],K:['110,30 110,230','290,30 110,145 290,230'],L:['110,30 110,230 290,230'],M:['90,230 90,30 200,140 310,30 310,230'],N:['110,230 110,30 290,230 290,30'],O:['150,30 250,30 290,75 290,185 250,230 150,230 110,185 110,75 150,30'],P:['110,230 110,30 240,30 290,75 240,130 110,130'],Q:['150,30 250,30 290,75 290,185 250,230 150,230 110,185 110,75 150,30','220,170 310,250'],R:['110,230 110,30 240,30 290,75 240,130 110,130','220,130 295,230'],S:['285,55 240,30 150,30 110,75 150,130 240,130 285,185 240,230 150,230 110,205'],T:['95,30 305,30','200,30 200,230'],U:['110,30 110,180 150,230 250,230 290,180 290,30'],V:['100,30 200,230 300,30'],W:['75,30 130,230 200,130 270,230 325,30'],X:['100,30 300,230','300,30 100,230'],Y:['100,30 200,130 300,30','200,130 200,230'],Z:['100,30 300,30 100,230 300,230']
};
const PR_DIGITS={0:PR_LETTERS.O,1:['150,75 200,30 200,230','150,230 250,230'],2:['110,70 150,30 250,30 290,75 270,115 110,230 290,230'],3:['110,30 280,30 200,125 270,150 290,190 250,230 130,230 100,200'],4:['260,230 260,30 100,165 310,165'],5:['290,30 110,30 110,125 240,125 290,170 270,210 230,230 140,230 100,200'],6:['280,40 210,30 130,85 110,175 140,225 245,230 290,185 260,130 170,130 110,175'],7:['100,30 300,30 160,230'],8:['200,125 120,75 150,30 250,30 280,75 200,125 110,180 145,230 255,230 290,180 200,125'],9:['290,115 250,135 150,135 110,85 145,30 250,30 290,75 290,185 250,230 140,230']};
function prAnswers(f,grade){const n=grade-1;return ({blocks:['0|1|0|1|2|1|0|1|0','1|0|1|2|1|2|3|2|3','3|2|1|0|1|0|1|2|3'],shapezones:['circle','square','triangle','circle|square','circle|triangle','square|triangle'],fruitsudoku:['🍎|🍊|🍇','🐱|🐸|🐻','⭐|💜|🔵'],analogy:['heart','star','circle','triangle'],pathtrace:['1','2','3','4','5','6'],countpictures:[String(2+n),String(4+n),String(6+n),String(8+n)],numbertrace:[String(1+n),String(3+n),String(5+n),String(7+n)],missingpicture:PR_ANIMALS,emotions:Object.keys(PR_FEEL),symbolgrid:[(1+n)+'|3|4','2|'+(4+n)+'|5','3|2|'+(6+n)],symmetrydraw:['0,0|2,1|1,2|3,3|0,4','1,0|3,1|2,2|3,3|1,4','0,1|2,0|3,2|2,4|0,3'],picturestrips:PR_ANIMALS,pictureadd:['2|'+(3+n),'4|'+(2+n),'5|'+(4+n)],rotatepicture:['0|1|3|2','1|2|0|3','2|3|1|0'],directions:['up|right','left|half','down|left','right|right'],lettertrace:grade===1?['A','B','C','D','E','F']:grade===2?['G','H','I','J','K','L']:['M','N','O','P','Q','R']})[f];}
for(const [id,c] of Object.entries(PRIMARY)){
 c.mode='SOLO';c.input='text';c.color=['#197fb0','#9950b9','#d35a7d','#198c7f'][Object.keys(PRIMARY).indexOf(id)%4];c.subject ||= 'math';ACTIVITIES[id]=c;FORMATS[id]={...c,description:c.rule,instructions:c.rule};
 for(const grade of [1,2,3])GAMES.push({id:c.subject+'-'+grade+'-'+id,format:id,subject:c.subject,grade,title:c.name+': Level '+grade,topic:id==='emotions'?'Naming feelings':id==='lettertrace'?'Capital letter formation':id==='pathtrace'?'Pre-writing and pen control':'Visual reasoning and early number skills',minutes:'8–12',items:prAnswers(id,grade).map(answer=>({prompt:c.rule.split('. ')[0]+'.',answer,options:[],hint:'',explanation:''}))});
}
function validatePrimary(raw,items){const f=raw.format;if(!PRIMARY[f])return;for(const q of items){const v=q.answer.split('|').map(x=>x.trim()),nums=v.map(Number);let ok=true;
 if(f==='blocks')ok=v.length===9&&v.every(n=>/^[0-3]$/.test(n));
 if(f==='shapezones')ok=v.length>=1&&v.length<=3&&new Set(v).size===v.length&&v.every(x=>PR_SHAPES.includes(x));
 if(f==='fruitsudoku')ok=v.length===3&&new Set(v).size===3&&v.every(x=>x.length>0&&x.length<=12);
 if(f==='analogy')ok=['heart','star','circle','triangle'].includes(q.answer);
 if(f==='pathtrace')ok=/^[1-6]$/.test(q.answer);
 if(f==='countpictures')ok=/^(?:[1-9]|1[0-2])$/.test(q.answer);
 if(f==='numbertrace')ok=/^[0-9]$/.test(q.answer);
 if(['missingpicture','picturestrips'].includes(f))ok=PR_ANIMALS.includes(q.answer);
 if(f==='emotions')ok=Object.keys(PR_FEEL).includes(q.answer);
 if(f==='symbolgrid')ok=v.length===3&&nums.every(n=>Number.isInteger(n)&&n>=1&&n<=9);
 if(f==='symmetrydraw')ok=v.length>=2&&v.length<=10&&v.every(x=>/^[0-3],[0-4]$/.test(x))&&v.every((x,i)=>!i||x!==v[i-1]);
 if(f==='pictureadd')ok=v.length===2&&nums.every(n=>Number.isInteger(n)&&n>=1&&n<=9);
 if(f==='rotatepicture')ok=v.length===4&&v.every(n=>/^[0-3]$/.test(n));
 if(f==='directions')ok=v.length===2&&['up','right','down','left'].includes(v[0])&&['right','left','half'].includes(v[1]);
 if(f==='lettertrace')ok=/^[A-Z]$/.test(q.answer);
 if(!ok)throw Error(PRIMARY[f].name+': '+PRIMARY[f].rule.split('Teacher answer: ')[1]);
}}
function prBtn(a,label,n='',disabled=false,extra=''){return '<button type="button" class="button secondary" data-mode-action="pr-'+a+'" data-value="'+n+'" '+(disabled?'disabled ':'')+extra+'>'+label+'</button>';}
function initPrimary(){game.session={engine:'activities',primary:true,groups:[],phase:'question',message:'',success:true};prRound();}
function prRound(){prepareRound();const s=game.session,f=game.lesson.format,q=current();s.phase='question';s.message='';s.selected=[];s.active=null;s.values=q.answer.split('|').map(x=>x.trim());s.board=Array(9).fill(0);s.turns=[0,0,0,0];s.order=shuffle([0,1,2]);s.slot=[];s.missing=Math.floor(Math.random()*4);s.small=game.index%2===0;s.target=game.index%3;
 if(f==='rotatepicture')s.turns=s.values.map(v=>(Number(v)+1+Math.floor(Math.random()*3))%4);
 if(f==='fruitsudoku'){const rows=shuffle([0,1,2]),cols=shuffle([0,1,2]);s.solution=rows.flatMap(r=>cols.map(c=>(r+c)%3));s.fixed=[0,1,3,4];s.board=s.solution.map((v,i)=>s.fixed.includes(i)?v:-1);s.active=0;}
 if(['pathtrace','numbertrace','lettertrace'].includes(f)){const paths=f==='lettertrace'?PR_LETTERS[q.answer]:f==='numbertrace'?PR_DIGITS[q.answer]:[Array.from({length:13},(_,i)=>{const x=35+i*27.5,y=130+Math.sin(i/12*Math.PI*(1+Number(q.answer)%3))*65*(Number(q.answer)%2?1:-1);return x+','+y;}).join(' ')];s.strokes=paths.map(p=>{const a=p.split(' ').map(v=>v.split(',').map(Number)),samples=[a[0]];for(let i=1;i<a.length;i++){const [x,y]=a[i-1],[u,v]=a[i],steps=Math.ceil(Math.hypot(u-x,v-y)/7);for(let k=1;k<=steps;k++)samples.push([x+(u-x)*k/steps,y+(v-y)*k/steps]);}return samples;});s.stroke=0;s.progress=0;s.ink=[];}
 if(f==='shapezones'){const wanted=[...s.values].sort().join('|'),points=[];for(let y=45;y<240;y+=10)for(let x=40;x<320;x+=10){const sets=prInside(x,y);if(sets.sort().join('|')===wanted&&prSafePoint(x,y))points.push([x,y]);}s.dot=shuffle(points)[0]||[180,140];}
 if(f==='analogy')s.options=shuffle(['correct','size','shape','both']);
 if(f==='directions'){const dirs=['up','right','down','left'];s.base=dirs.indexOf(s.values[0]);s.delta={right:1,left:3,half:2}[s.values[1]];s.bottom=(s.base+1)%4;}
}
function prInside(x,y){return [Math.hypot(x-150,y-125)<85?'circle':'',x>160&&x<300&&y>80&&y<220?'square':'',y>60&&y<240&&x>80+(y-60)*.75&&x<330-(y-60)*.64?'triangle':''].filter(Boolean);}
function prSafePoint(x,y){const a=prInside(x,y).sort().join('|');return [[-8,0],[8,0],[0,-8],[0,8]].every(([dx,dy])=>prInside(x+dx,y+dy).sort().join('|')===a);}
function prScore(good){game.attempts++;game.feedbackGood=good;const s=game.session;if(good){game.correct++;game.score+=100;game.answered=true;s.phase='feedback';s.message='Brilliant — you solved it!';}else s.message='Keep exploring. You can change your answer and try again.';}
function prAnimal(name,view='0 0 300 240'){const colors={monkey:['#c98840','#f7cc8b'],cat:['#f8bb53','#fff0be'],bear:['#9b694d','#dcb88b'],frog:['#69be79','#ceef9f']},[c,d]=colors[name];return '<svg viewBox="'+view+'" role="img" aria-label="'+name+' picture"><rect width="300" height="240" fill="#fff0c5"/><circle cx="65" cy="85" r="42" fill="'+c+'"/><circle cx="235" cy="85" r="42" fill="'+c+'"/><ellipse cx="150" cy="135" rx="100" ry="92" fill="'+c+'"/><ellipse cx="150" cy="150" rx="77" ry="65" fill="'+d+'"/><circle cx="113" cy="112" r="12" fill="#34324d"/><circle cx="187" cy="112" r="12" fill="#34324d"/><circle cx="109" cy="108" r="4" fill="white"/><circle cx="183" cy="108" r="4" fill="white"/><ellipse cx="150" cy="149" rx="12" ry="8" fill="#634332"/><path d="M115 172 Q150 207 185 172" stroke="#634332" stroke-width="7" fill="none" stroke-linecap="round"/>'+(name==='cat'?'<path d="M75 60L70 15L117 50M183 50L230 15L225 60" fill="'+c+'" stroke="#b6853f" stroke-width="4"/>':'')+'</svg>';}
function prShape(shape,small){const chars={heart:'♥',circle:'●',star:'★',triangle:'▲'};return '<span class="pr-shape '+(small?'small':'')+'">'+chars[shape]+'</span>';}
function prTile(turn){return '<svg viewBox="0 0 100 100" style="transform:rotate('+turn*90+'deg)"><rect width="100" height="100" fill="#9354cf"/><path d="M0 0H100A100 100 0 0 1 0 100Z" fill="#ffe470"/><circle cx="22" cy="22" r="8" fill="#ff9f56"/></svg>';}
function prBlocks(values){let h='<svg viewBox="0 0 330 300" aria-label="Block height model">';for(let r=0;r<3;r++)for(let c=0;c<3;c++){const x=165+(c-r)*45,y=100+(c+r)*23,n=Number(values[r*3+c]);h+='<path d="M'+x+' '+y+'l45 23 -45 23 -45 -23Z" fill="#e8e0f8" stroke="white"/>';for(let z=0;z<n;z++){const t=y-(z+1)*26;h+='<path d="M'+(x-45)+' '+(t+23)+'l45 23v26l-45-23Z" fill="#d393ee" stroke="#b87ddd"/><path d="M'+x+' '+(t+46)+'l45-23v26l-45 23Z" fill="#9154c6" stroke="#7a46af"/><path d="M'+x+' '+t+'l45 23 -45 23 -45-23Z" fill="#ffe071" stroke="#f0c65a"/>';}h+='<text x="'+x+'" y="'+(y-n*26+29)+'" text-anchor="middle" fill="#423155" font-size="18" font-weight="bold">'+n+'</text>';}return h+'</svg>';}
function renderPrimary(){const f=game.lesson.format,c=PRIMARY[f],s=game.session,q=current();$('#play-title').textContent=game.lesson.title;$('#play-format').textContent=c.name;$('#play-subtitle').textContent='Solo · Grade '+game.lesson.grade;$('.player-bottom>span').textContent='Take your time. Explore, explain and try again.';$('#scoreboard').innerHTML='<div class="class-score"><strong>⭐ '+game.correct+' / '+game.items.length+' solved</strong><span>'+game.score+' points</span></div>';let h='<h2>'+esc(q.prompt)+'</h2>';
 if(game.done)h='<div class="result"><div class="result-icon">🏆</div><h2>Wonderful work! All puzzles solved.</h2><div class="result-actions"><button class="button primary" data-replay>Play again</button><button class="button secondary" data-edit-result>Edit lesson</button></div></div>';
 else if(s.phase==='feedback')h='<div class="pr-win">🌟</div><h2>'+esc(s.message)+'</h2>'+prBtn('next','Next puzzle →');
 else if(f==='blocks')h+='<div class="pr-two"><div><h3>Copy this model</h3>'+prBlocks(s.values)+'</div><div><h3>Your block heights</h3><div class="pr-grid nine">'+s.board.map((v,i)=>prBtn('height','<span>'+('🧱'.repeat(v)||'·')+'</span><b>'+v+'</b>',i)).join('')+'</div></div></div>'+prBtn('check','Check model');
 else if(f==='shapezones')h+='<div class="pr-two"><svg viewBox="0 0 380 280" class="pr-scene"><circle cx="150" cy="125" r="85" fill="#ac83ed22" stroke="#9862d1" stroke-width="5"/><rect x="160" y="80" width="140" height="140" fill="#61cba422" stroke="#26ad80" stroke-width="5"/><path d="M80 60L330 60L215 240Z" fill="#fd806922" stroke="#ec685f" stroke-width="5"/><text x="'+s.dot[0]+'" y="'+(s.dot[1]+7)+'" text-anchor="middle" font-size="24">🐞</text></svg><div class="pr-choices">'+PR_SHAPES.map((v,i)=>prBtn('shape',esc(v),i,false,'aria-pressed="'+s.selected.includes(v)+'"')).join('')+prBtn('check','Check shapes')+'</div></div>';
 else if(f==='fruitsudoku')h+='<div class="pr-sudoku"><div class="pr-grid nine">'+s.board.map((v,i)=>prBtn('cell',v<0?'?':esc(s.values[v]),i,s.fixed.includes(i),'data-fixed="'+s.fixed.includes(i)+'"')).join('')+'</div><div class="pr-choices">'+s.values.map((v,i)=>prBtn('fruit',esc(v),i,false,'aria-pressed="'+(s.active===i)+'"')).join('')+prBtn('check','Check grid')+'</div></div>';
 else if(f==='analogy'){const other=q.answer==='circle'?'star':'circle';h+='<div class="pr-analogy"><div>'+prShape(other,!s.small)+' → '+prShape(other,s.small)+'</div><div>'+prShape(q.answer,!s.small)+' → <b>?</b></div></div><div class="pr-options">'+s.options.map((v,i)=>prBtn('analogy',prShape(v==='shape'||v==='both'?other:q.answer,v==='size'||v==='both'?!s.small:s.small),i)).join('')+'</div>';}
 else if(['pathtrace','numbertrace','lettertrace'].includes(f))h+='<div class="pr-tracing"><svg id="pr-trace" viewBox="0 0 400 270" aria-label="Trace the highlighted stroke"><rect width="400" height="270" rx="20" fill="#f2f6ff"/>'+(f==='pathtrace'?'<text x="4" y="136" font-size="24">🦋</text><text x="372" y="137" font-size="24">🌼</text>':'')+s.strokes.map((pts,i)=>'<polyline points="'+pts.map(p=>p.join(',')).join(' ')+'" fill="none" stroke="'+(i<s.stroke?'#20b994':'#b8b4d8')+'" stroke-width="12" stroke-linejoin="round" stroke-linecap="round" stroke-dasharray="'+(i<s.stroke?'0':'2 17')+'"/>').join('')+'<polyline id="pr-ink" points="'+s.ink.map(p=>p.join(',')).join(' ')+'" fill="none" stroke="#8c4dd1" stroke-width="9" stroke-linecap="round"/><circle id="pr-start" cx="'+s.strokes[s.stroke][s.progress][0]+'" cy="'+s.strokes[s.stroke][s.progress][1]+'" r="10" fill="#1aaf7c"/></svg><p>Stroke '+(s.stroke+1)+' of '+s.strokes.length+' · Start at the green dot</p>'+prBtn('resettrace','Start this stroke again')+'</div>';
 else if(f==='countpictures'||f==='pictureadd'){const a=Number(s.values[0]),b=f==='pictureadd'?Number(s.values[1]):0,total=a+b,answers=shuffle([total,total+1,Math.max(0,total-1),total+2]);if(!s.choices)s.choices=answers;h+='<div class="pr-count"><div>'+('🍊'.repeat(a))+'</div>'+(b?'<b>+</b><div>'+('🍎'.repeat(b))+'</div>':'')+'</div><div class="pr-options">'+s.choices.map((v,i)=>prBtn('number',String(v),i)).join('')+'</div>';}
 else if(f==='missingpicture')h+='<div class="pr-pieces"><div class="pr-whole">'+prAnimal(q.answer)+'<div class="pr-hole" style="left:'+(s.missing%2*50)+'%;top:'+Math.floor(s.missing/2)*50+'%">?</div></div><div class="pr-options">'+[0,1,2,3].map(i=>prBtn('piece',prAnimal(q.answer,(i%2*150)+' '+Math.floor(i/2)*120+' 150 120'),i)).join('')+'</div></div>';
 else if(f==='emotions')h+='<h3 class="pr-feeling">'+esc(q.answer)+'</h3><div class="pr-options feelings">'+Object.entries(PR_FEEL).map(([word,face],i)=>prBtn('feeling',face,i,false,'aria-label="'+word+' face"')).join('')+'</div>';
 else if(f==='symbolgrid'){const nums=s.values.map(Number),grid=[[0,0,0],[0,1,1],[1,2,2]],icons=['🍰','🟩','🧊'];h+='<div class="pr-two"><div class="pr-equations">'+grid.map(row=>'<div>'+row.map(i=>'<span>'+icons[i]+'</span>').join('')+'<b>= '+row.reduce((a,i)=>a+nums[i],0)+'</b></div>').join('')+'<div class="pr-totals">'+[0,1,2].map(col=>'<b>'+grid.reduce((a,row)=>a+nums[row[col]],0)+'</b>').join('')+'<small>column totals</small></div></div><form id="pr-form"><label>'+icons[s.target]+' = ?<input id="pr-number" inputmode="numeric" autocomplete="off" maxlength="2" aria-label="Hidden picture value"></label><button class="button primary">Check value</button></form></div>';}
 else if(f==='symmetrydraw'){const pts=s.values.map(v=>v.split(',').map(Number));h+='<div class="pr-mirror"><svg viewBox="0 0 440 280" aria-label="Copy the reflected line"><path d="M220 0V280" stroke="#ee7d65" stroke-dasharray="8 6" stroke-width="3"/><polyline points="'+pts.map(([x,y])=>[25+x*45,30+y*50].join(',')).join(' ')+'" fill="none" stroke="#f0a440" stroke-width="5"/><polyline points="'+s.selected.map(i=>[415-(i%4)*45,30+Math.floor(i/4)*50].join(',')).join(' ')+'" fill="none" stroke="#8c55ce" stroke-width="5"/>'+Array.from({length:20},(_,i)=>'<circle cx="'+(25+i%4*45)+'" cy="'+(30+Math.floor(i/4)*50)+'" r="4" fill="#9897b5"/><circle data-mode-action="pr-dot" data-value="'+i+'" tabindex="0" role="button" aria-label="Right-side column '+(i%4+1)+' row '+(Math.floor(i/4)+1)+'" cx="'+(415-i%4*45)+'" cy="'+(30+Math.floor(i/4)*50)+'" r="16" fill="#8c55ce33" stroke="#8c55ce"/>').join('')+'</svg></div><div class="pr-options">'+prBtn('undo','Undo')+prBtn('check','Check reflection')+'</div>';}
 else if(f==='picturestrips')h+='<div class="pr-strip-layout"><div class="pr-reference">'+prAnimal(q.answer)+'</div><div><div class="pr-strips" id="pr-strip-target">'+[0,1,2].map((_,i)=>s.slot[i]===undefined?'<span class="pr-empty">'+(i+1)+'</span>':prBtn('unstrip',prAnimal(q.answer,(s.slot[i]*100)+' 0 100 240'),i)).join('')+'</div><div class="pr-strips">'+s.order.map(i=>prBtn('strip',prAnimal(q.answer,(i*100)+' 0 100 240'),i,s.slot.includes(i),'draggable="true" data-pr-drag="'+i+'"')).join('')+'</div></div></div>'+prBtn('check','Check picture');
 else if(f==='rotatepicture')h+='<div class="pr-two"><div><h3>Model</h3><div class="pr-rotate">'+s.values.map(v=>'<div>'+prTile(Number(v))+'</div>').join('')+'</div></div><div><h3>Tap to turn</h3><div class="pr-rotate">'+s.turns.map((v,i)=>prBtn('rotate',prTile(v),i,false,'aria-label="Rotate tile '+(i+1)+'"')).join('')+'</div></div></div>'+prBtn('check','Check tiles');
 else if(f==='directions'){const arrows=['↑','→','↓','←'];h+='<div class="pr-analogy"><div>'+arrows[s.base]+' ➜ '+arrows[(s.base+s.delta)%4]+'</div><div>'+arrows[s.bottom]+' ➜ ?</div></div><div class="pr-options">'+arrows.map((v,i)=>prBtn('direction',v,i)).join('')+'</div>';}
 if(!game.done&&s.phase!=='feedback')h+='<p class="pr-status" role="status">'+esc(s.message)+'</p>';$('#arena').innerHTML='<div class="pr-game">'+h+'</div>';$('#arena').classList.add('activity-arena');prBind();
}
function prBind(){const s=game.session;if($('#pr-form'))$('#pr-form').onsubmit=e=>{e.preventDefault();handlePrimary({dataset:{modeAction:'pr-value'}});};if($('#pr-trace')){const el=$('#pr-trace');let active=null;const move=e=>{if(active!==e.pointerId)return;const pos=new DOMPoint(e.clientX,e.clientY).matrixTransform(el.getScreenCTM().inverse()),x=pos.x,y=pos.y,pts=s.strokes[s.stroke];let next=s.progress;for(let i=s.progress;i<=Math.min(pts.length-1,s.progress+4);i++)if(Math.hypot(pts[i][0]-x,pts[i][1]-y)<=19)next=i;if(next===s.progress)return;s.progress=next;s.ink=pts.slice(0,next+1);$('#pr-ink')?.setAttribute('points',s.ink.map(p=>p.join(',')).join(' '));$('#pr-start')?.setAttribute('cx',pts[next][0]);$('#pr-start')?.setAttribute('cy',pts[next][1]);if(next===pts.length-1){active=null;s.stroke++;if(s.stroke===s.strokes.length)prScore(true);else{s.progress=0;s.ink=[];}renderGame();}};el.onpointerdown=e=>{if(active!==null)return;const pos=new DOMPoint(e.clientX,e.clientY).matrixTransform(el.getScreenCTM().inverse()),[x,y]=s.strokes[s.stroke][s.progress];if(Math.hypot(pos.x-x,pos.y-y)>22)return;active=e.pointerId;el.setPointerCapture(e.pointerId);e.preventDefault();};el.onpointermove=move;el.onpointerup=el.onpointercancel=()=>active=null;}
 document.querySelectorAll('[data-pr-drag]').forEach(el=>el.ondragstart=e=>e.dataTransfer.setData('text/plain',el.dataset.prDrag));if($('#pr-strip-target')){$('#pr-strip-target').ondragover=e=>e.preventDefault();$('#pr-strip-target').ondrop=e=>{e.preventDefault();const n=e.dataTransfer.getData('text/plain');if(/^[0-2]$/.test(n))handlePrimary({dataset:{modeAction:'pr-strip',value:n}});};}
 document.querySelectorAll('[data-mode-action="pr-dot"]').forEach(el=>{el.onclick=()=>handlePrimary(el);el.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();handlePrimary(el);}};});
}
function handlePrimary(button){if(game.done||ui.view!=='player'||button.disabled)return;const s=game.session,f=game.lesson.format,a=button.dataset.modeAction.slice(3),n=Number(button.dataset.value);if(s.phase==='feedback'){if(a==='next'){game.index++;if(game.index===game.items.length){game.index--;game.done=true;}else{s.choices=null;prRound();}renderGame();}return;}
 if(a==='height'&&f==='blocks'&&n>=0&&n<9)s.board[n]=(s.board[n]+1)%4;
 else if(a==='shape'&&f==='shapezones'&&PR_SHAPES[n]){const v=PR_SHAPES[n];s.selected=s.selected.includes(v)?s.selected.filter(x=>x!==v):[...s.selected,v];}
 else if(a==='fruit'&&f==='fruitsudoku'&&n>=0&&n<3)s.active=n;
 else if(a==='cell'&&f==='fruitsudoku'&&n>=0&&n<9&&!s.fixed.includes(n))s.board[n]=s.active;
 else if(a==='analogy'&&f==='analogy'&&s.options[n])prScore(s.options[n]==='correct');
 else if(a==='resettrace'&&s.strokes){s.progress=0;s.ink=[];}
 else if(a==='number'&&['countpictures','pictureadd'].includes(f)&&s.choices[n]!==undefined)prScore(s.choices[n]===s.values.map(Number).reduce((a,b)=>a+b,0));
 else if(a==='piece'&&f==='missingpicture'&&n>=0&&n<4)prScore(n===s.missing);
 else if(a==='feeling'&&f==='emotions'&&Object.keys(PR_FEEL)[n])prScore(Object.keys(PR_FEEL)[n]===current().answer);
 else if(a==='value'&&f==='symbolgrid'){const value=$('#pr-number').value.trim();if(!/^\d+$/.test(value)){s.message='Type a whole number first.';}else prScore(Number(value)===Number(s.values[s.target]));}
 else if(a==='dot'&&f==='symmetrydraw'&&n>=0&&n<20&&s.selected.length<s.values.length)s.selected.push(n);
 else if(a==='undo'&&f==='symmetrydraw')s.selected.pop();
 else if(a==='strip'&&f==='picturestrips'&&n>=0&&n<3&&!s.slot.includes(n))s.slot.push(n);
 else if(a==='unstrip'&&f==='picturestrips'&&n>=0&&n<s.slot.length)s.slot.splice(n,1);
 else if(a==='rotate'&&f==='rotatepicture'&&n>=0&&n<4)s.turns[n]=(s.turns[n]+1)%4;
 else if(a==='direction'&&f==='directions'&&n>=0&&n<4)prScore(n===(s.bottom+s.delta)%4);
 else if(a==='check'){
  if(f==='blocks')prScore(s.board.every((v,i)=>v===Number(s.values[i])));
  if(f==='shapezones')prScore([...s.selected].sort().join('|')===[...s.values].sort().join('|'));
  if(f==='fruitsudoku')prScore(s.board.every(v=>v>=0)&&[0,1,2].every(i=>new Set(s.board.slice(i*3,i*3+3)).size===3&&new Set([s.board[i],s.board[i+3],s.board[i+6]]).size===3));
  if(f==='symmetrydraw')prScore([s.selected,[...s.selected].reverse()].some(path=>path.map(i=>i%4+','+Math.floor(i/4)).join('|')===s.values.join('|')));
  if(f==='picturestrips')prScore(s.slot.join('|')==='0|1|2');
  if(f==='rotatepicture')prScore(s.turns.every((v,i)=>v===Number(s.values[i])));
 }
 renderGame();
}

function primaryEditorRows(){if(!PRIMARY[draft?.format])return;document.querySelectorAll("[data-row]").forEach(row=>{const i=Number(row.dataset.row),answer=row.querySelector("[data-field=answer]");answer.parentElement.firstChild.textContent="Puzzle setup · ";const presets=[...new Set([...prAnswers(draft.format,Math.min(3,Math.max(1,draft.grade))),draft.items[i].answer])];const label=document.createElement("label");label.textContent="Choose a ready-made variation";const select=document.createElement("select");presets.forEach((v,n)=>{const option=document.createElement("option");option.value=v;option.textContent=(n+1)+". "+v;select.append(option);});select.value=draft.items[i].answer;select.onchange=()=>{draft.items[i].answer=select.value;answer.value=select.value;dirty=true;};label.append(select);row.insertBefore(label,answer.parentElement);});}
